def next_higher(start, k):
    n = start + 1
    while True:
        product = n * k
        partition_sums = set()
        for i in range(1, len(str(product)) + 1):
            for j in range(i + 1, len(str(product)) + 1):
                partition_sums.add(int(str(product)[:i]) + int(str(product)[i:j]) + int(str(product)[j:]))
        if start + 1 == n and sum(map(int, str(product))) == n:
            return n + 1
        if n in partition_sums:
            return n
        n += 1

