def is_subset_sum_divisible(arr, m):
    n = len(arr)
    dp = [False] * m
    dp[0] = True
    for num in arr:
        new_dp = dp[:]
        for i in range(m - num, -1, -1):
            if dp[i]:
                new_dp[i + num] = True
        dp = new_dp
    return dp[0]
